candidates<-d[d$Magnitude>6,];dc<-decluster(candidates);peaks<-dc[!dc$cluster_removed,]
write_table(dc[,c('ID','timestamp','Magnitude','Longitude','Latitude','cluster_removed','cluster_parent')],'declustering')
grid <- seq(6,7.6,.1)
stability <- function(peaks) do.call(rbind,lapply(grid,function(u){x<-peaks$Magnitude;if(sum(x>u)<30)return(NULL);f<-gpd_fit(x,u);data.frame(u=u,n=sum(x>u),excesso_medio=mean(x[x>u]-u),EP_excesso=sd(x[x>u]-u)/sqrt(sum(x>u)),sigma=f$estimate[1],xi=f$estimate[2],EP_xi=f$std.err[2],sigma_mod=f$estimate[1]-f$estimate[2]*u)}))
st<-stability(peaks);write_table(st,'thresholds')
# Limiar decidido após inspeção dos diagnósticos; ver discussão no relatório.
u<-7
pot<-gpd_fit(peaks$Magnitude,u);lambda<-sum(peaks$Magnitude>u)/52
B<-399;pb<-matrix(NA_real_,B,8)
for(b in 1:B){years<-sample(1965:2016,52,replace=TRUE);x<-unlist(lapply(years,function(y)peaks$Magnitude[peaks$ano==y]));f<-tryCatch(gpd_fit(x,u),error=function(e)NULL);if(!is.null(f)&&f$convergence=='successful')pb[b,]<-c(f$estimate,gpd_return(f,u,sum(x>u)/52,c(2,5,10,20,50,100)))}
write_table(data.frame(parametro=c('sigma','xi'),estimativa=unname(pot$estimate),EP=unname(pot$std.err),inferior=apply(pb[,1:2],2,ci)[1,],superior=apply(pb[,1:2],2,ci)[2,],u=u,excedencias=sum(peaks$Magnitude>u),lambda=lambda,bootstrap_validos=sum(complete.cases(pb)),bootstrap_total=B),'gpd')
pr<-data.frame(T=c(2,5,10,20,50,100),magnitude=gpd_return(pot,u,lambda,c(2,5,10,20,50,100)),inferior=apply(pb[,3:8],2,ci)[1,],superior=apply(pb[,3:8],2,ci)[2,]);write_table(pr,'retorno_gpd')
write_table(data.frame(metodo=c('GEV anual','GPD clusters'),xi=c(global$fit$estimate[3],pot$estimate[2]),inferior=c(ci(global$boot[,3])[1],ci(pb[,2])[1]),superior=c(ci(global$boot[,3])[2],ci(pb[,2])[2])),'comparacao_metodos')
fig('threshold',function(){par(mfrow=c(2,2));with(st,{plot(u,excesso_medio,type='b',main='Excesso médio após agrupamento',xlab='Limiar u',ylab='Excesso médio');arrows(u,excesso_medio-1.96*EP_excesso,u,excesso_medio+1.96*EP_excesso,angle=90,code=3,length=.03);plot(u,xi,type='b',main='Estabilidade de xi',xlab='Limiar u',ylab='xi');arrows(u,xi-1.96*EP_xi,u,xi+1.96*EP_xi,angle=90,code=3,length=.03);plot(u,sigma_mod,type='b',main='Escala modificada',xlab='Limiar u',ylab='sigma(u) - xi u');plot(u,n,type='b',main='Excedências disponíveis',xlab='Limiar u',ylab='n')})})
fig('diagnostico_gpd',function(){par(mfrow=c(2,2));x<-sort(peaks$Magnitude[peaks$Magnitude>u]-u);p<-ppoints(length(x));plot(evd::qgpd(p,scale=pot$estimate[1],shape=pot$estimate[2]),x,main='QQ: excessos GPD',xlab='Quantis ajustados',ylab='Excessos observados');abline(0,1);plot(p,evd::pgpd(x,scale=pot$estimate[1],shape=pot$estimate[2]),main='PP: GPD',xlab='Probabilidade empírica',ylab='Probabilidade ajustada');abline(0,1);plot(pr$T,pr$magnitude,type='b',log='x',ylim=range(pr[,2:4]),main='Retorno GPD e IC95%',xlab='Anos',ylab='Magnitude');arrows(pr$T,pr$inferior,pr$T,pr$superior,angle=90,code=3,length=.03);lines(global$ret$T,global$ret$magnitude,col='#007f78');legend('topleft',c('GPD','GEV'),col=c('black','#007f78'),lty=1);hist(x,prob=TRUE,col='#b8ded8',main='Excessos: dados e modelo',xlab='Magnitude - u');xx<-seq(0,max(x),length.out=100);lines(xx,evd::dgpd(xx,scale=pot$estimate[1],shape=pot$estimate[2]),col='#007f78')})
sensdc<-do.call(rbind,lapply(c(.5,1,2),function(k){z<-decluster(candidates,k);x<-z$Magnitude[!z$cluster_removed];f<-gpd_fit(x,u);data.frame(fator_janela=k,candidatos=nrow(z),retidos=length(x),excedencias=sum(x>u),xi=f$estimate[2],EP=f$std.err[2])}));write_table(sensdc,'sensibilidade_declustering')
